core:
var LEX={love:2,great:2,happy:2,good:1,excellent:3,best:3,like:1,awesome:3,wonderful:3,amazing:3,perfect:3,
  hate:-2,terrible:-2,bad:-1,awful:-3,worst:-3,sad:-1,dislike:-1,poor:-1,ugly:-2,horrible:-3,boring:-1};
function analyze(text){ text=String(text||'').toLowerCase(); var words=(text.match(/[a-z']+/g)||[]);
  var score=0,pos=0,neg=0;
  for(var i=0;i<words.length;i++){ var w=words[i]; if(LEX[w]!=null){ if(LEX[w]>0){pos++;score+=LEX[w];} else {neg++;score+=LEX[w];} } }
  var label= score>0?'positive': score<0?'negative':'neutral';
  return {score:score, pos:pos, neg:neg, label:label}; }
var EXPORTS={analyze:analyze, LEX:LEX};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.SentimentForgePure = EXPORTS; }
